function codeSearch(params) {
  return async ({ query: userText }, { abortSignal }) => {
    try {
      const results = await retrieve(
        {
          chatMessageId: params.messageId || "messageId",
          userText,
          workspaceFolders: {
            rootPaths: params.rootPaths
          },
          filterByLanguage: params.filterByLanguage || false,
          localScope: params.localScope,
          remoteScope: params.remoteScope,
          openFilePath: params.openFilePath,
          allowListRepos: params.allowListRepos,
          allowListRemoteFiles: params.allowListRemoteFiles
        },
        abortSignal
      );
      return {
        retrievalId: results.retrievalId,
        documents: results.documents,
        externalDocuments: results.externalDocuments,
        preferredDocuments: results.preferredDocuments
      };
    } catch (error41) {
      logger_default.error("Code Search tool error:", error41);
      return {
        error: error41,
        message: "Failed to retrieve relevant code for the given query."
      };
    }
  };
}

