// src/controllers/getMcpsController.ts
function mcpServersToUiMcpServers(servers, permissionMap, isToolDisabled) {
  return servers.map((server) => {
    const { configFileName, serverName } = server.config;
    const id = getMcpServerKey(configFileName, serverName);
    const permission = permissionMap.get(id) ?? "auto-approve";
    switch (server.state) {
      case "connected":
      case "error":
        return {
          id,
          serverName,
          permission,
          error: server.mcpServerError,
          tools: server.tools?.map((tool2) => {
            const toolId = getMcpToolKey(
              configFileName,
              serverName,
              tool2.toolDisplayName
            );
            return {
              toolId,
              mcpServerName: serverName,
              toolDisplayName: tool2.toolDisplayName,
              toolName: tool2.toolName,
              mcpServerPermission: permission,
              isAvailable: !isToolDisabled(toolId)
            };
          })
        };
      case "blocked":
        return {
          id,
          serverName,
          permission,
          error: server.blockReason ?? "Blocked by organization"
        };
      case "disabled":
        return {
          id,
          serverName,
          permission,
          error: "Disabled by user"
        };
      case "initializing":
        return {
          id,
          serverName,
          permission
        };
      case "authorizing":
        return {
          id,
          serverName,
          permission,
          error: "Authorizing"
        };
      case "needAuthorization":
        return {
          id,
          serverName,
          permission,
          error: "Need authorization"
        };
      case "authorized":
        return {
          id,
          serverName,
          permission,
          error: "authorized"
        };
    }
  });
}
function createGetMcpsController(mcpManager, mcpPermissionService, mcpDisabledToolsService) {
  return async (req, res) => {
    try {
      await mcpManager.loadMcpServers({
        rootPath: req.query.rootPath,
        dontChangeDisabled: true
      });
      const userMcpServers = mcpManager.getUserMcpServers();
      const nativeMcpServers = mcpManager.getNativeMcpServers();
      const allPermissions = await mcpPermissionService.getAllPermissions();
      const permissionMap = new Map(
        allPermissions.map((p) => [p.mcpId, p.permission])
      );
      const isToolDisabled = await mcpDisabledToolsService.getIsToolDisabledPredicate([
        ...userMcpServers,
        ...nativeMcpServers
      ]);
      res.json({
        mcpServers: {
          userMcpServers: mcpServersToUiMcpServers(
            userMcpServers,
            permissionMap,
            isToolDisabled
          ),
          nativeMcpServers: mcpServersToUiMcpServers(
            nativeMcpServers,
            permissionMap,
            isToolDisabled
          )
        }
      });
    } catch (error41) {
      logger_default.error("Failed retrieving mcp servers", { error: error41 });
      res.status(500).json({
        error: "Failed to retrieve mcp servers",
        message: "Failed to retrieve mcp servers"
      });
    }
  };
}

